const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry for Denmark
  var denmark = ee.FeatureCollection('FAO/GAUL/2015/level0')
                    .filter(ee.Filter.eq('ADM0_NAME', 'Denmark'));
  var geometry = denmark.geometry();

  // 2. Define dates
  var date2017 = '2017-07-19';
  var date2018 = '2018-07-24';

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    var qa = image.select('QA60');
    var cloudBitMask = 1 << 10;
    var cirrusBitMask = 1 << 11;
    var mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Cloud masking for Landsat 8
  function maskL8clouds(image) {
    var qa = image.select('QA_PIXEL');
    var cloudShadowBitMask = 1 << 3;
    var cloudsBitMask = 1 << 5;
    var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                 .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to get NDVI image for a given date with fallbacks
  async function getNDVI(dateStr) {
    var date = ee.Date(dateStr);

    // Try Sentinel-2 exact date
    var s2_exact = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                     .filterDate(date, date.advance(1, 'day'))
                     .filterBounds(geometry)
                     .map(maskS2clouds);
    var count = await s2_exact.size().getInfo();
    if (count > 0) {
      var image = s2_exact.median();
      var ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      return {ndvi: ndvi, source: 'Sentinel-2 (exact)', imageCount: count};
    }

    // Try Sentinel-2 with 3-day window
    var s2_3day = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                    .filterDate(date.advance(-1, 'day'), date.advance(2, 'day'))
                    .filterBounds(geometry)
                    .map(maskS2clouds);
    count = await s2_3day.size().getInfo();
    if (count > 0) {
      image = s2_3day.median();
      ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      return {ndvi: ndvi, source: 'Sentinel-2 (3-day)', imageCount: count};
    }

    // Try Landsat 8 with 3-day window
    var l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
                .filterDate(date.advance(-1, 'day'), date.advance(2, 'day'))
                .filterBounds(geometry)
                .map(maskL8clouds);
    count = await l8.size().getInfo();
    if (count > 0) {
      image = l8.median();
      ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
      return {ndvi: ndvi, source: 'Landsat8 (3-day)', imageCount: count};
    }

    return null; // No data
  }

  // Get NDVI for both dates
  var ndvi2017 = await getNDVI(date2017);
  var ndvi2018 = await getNDVI(date2018);

  // Check for no data (C1)
  if (!ndvi2017 || !ndvi2018) {
    console.log('2017 Images: ' + (ndvi2017 ? ndvi2017.imageCount : 0));
    console.log('2018 Images: ' + (ndvi2018 ? ndvi2018.imageCount : 0));
    console.log('<answer>C1</answer>');
    return;
  }

  // Function to compute stats
  async function computeStats(ndviImage, label) {
    var stats = ndviImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });
    return await stats.getInfo();
  }

  // Compute stats
  var stats2017 = await computeStats(ndvi2017.ndvi, '2017-07-19');
  var stats2018 = await computeStats(ndvi2018.ndvi, '2018-07-24');

  var mean2017 = stats2017.NDVI_mean;
  var count2017 = stats2017.NDVI_count;
  var mean2018 = stats2018.NDVI_mean;
  var count2018 = stats2018.NDVI_count;

  // Print evidence (concise)
  console.log('2017-07-19: NDVI=' + mean2017.toFixed(3) + 
              ', Pixels=' + count2017 + 
              ', Source=' + ndvi2017.source);
  console.log('2018-07-24: NDVI=' + mean2018.toFixed(3) + 
              ', Pixels=' + count2018 + 
              ', Source=' + ndvi2018.source);

  // Check for no valid pixels (C2)
  if (count2017 === 0 || count2018 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // Check for invalid values (C3)
  if (mean2017 === null || mean2018 === null ||
      isNaN(mean2017) || isNaN(mean2018) ||
      Math.abs(mean2017) > 1.5 || Math.abs(mean2018) > 1.5) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare: lower NDVI means more brown
  if (mean2018 < mean2017) {
    console.log('2018 NDVI lower -> more brown in 2018.');
    console.log('<answer>A</answer>');
  } else {
    console.log('2018 NDVI not lower -> not more brown in 2018.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
